import{_ as s,c as t,o as n,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"《杭氏易学-易楔》简介","description":"杭氏易学 - 《杭氏易学-易楔》简介","frontmatter":{"title":"《杭氏易学-易楔》简介","description":"杭氏易学 - 《杭氏易学-易楔》简介"},"headers":[],"relativePath":"zh/classics/hangshi/001.md","filePath":"zh/classics/hangshi/001.md"}'),l={name:"zh/classics/hangshi/001.md"};function i(c,a,o,d,p,h){return n(),t("div",null,[...a[0]||(a[0]=[e("h1",{id:"《杭氏易学-易楔》简介",tabindex:"-1"},[r("《杭氏易学-易楔》简介 "),e("a",{class:"header-anchor",href:"#《杭氏易学-易楔》简介","aria-label":"Permalink to “《杭氏易学-易楔》简介”"},"​")],-1),e("p",null,"《易楔》是近代易学大家杭辛斋的易学著作之一。杭辛斋，生活在1869年至1924年之间。杭辛斋在易学领域有着深厚的造诣和独特的见解，他立足于象数，重整象数体系，企图将象数扩展为融数学、科技、术数为一炉的无所不包的易学体系。",-1),e("p",null,"杭辛斋的易学著作包括《易楔》、《学易笔谈》、《易数偶得》、《读易杂记》等多种，这些著作合称《杭氏易学七种》。这些作品展示了杭辛斋对《周易》象数研究的深邃见解，以及象数在自然科学方面的应用，对现代自然科学的研究具有较大的启示作用。",-1),e("p",null,"此外，杭辛斋还组织过《周易》学术研究会，名为研几学社，并在学社中担任《周易》主讲，撰写《周易》讲义。杭辛斋的易学思想融合了汉代易学、宋代图书之学的特点，同时又具有世界眼光，为易学的发展开辟了新的道路。",-1),e("p",null,"总之，杭氏易学是一个具有深厚理论基础和丰富实践经验的易学体系，对于研究易学和了解中国传统文化具有重要意义。",-1)])])}const f=s(l,[["render",i]]);export{_ as __pageData,f as default};
